package com.superiptv.app.data.local
import android.content.Context
import androidx.room.*
import kotlinx.coroutines.flow.Flow
@Entity(tableName="playlists") data class PlaylistEntity(@PrimaryKey val id:String,val name:String,val source:String,val sourceType:String,val createdAt:Long,val updatedAt:Long)
@Entity(tableName="channels",indices=[Index("playlistId"),Index("groupName")]) data class ChannelEntity(@PrimaryKey val id:String,val playlistId:String,val name:String,val streamUrl:String,val logoUrl:String?,val groupName:String,val favorite:Boolean=false)
@Entity(tableName="vod_items",indices=[Index("contentType"),Index("groupName"),Index("seriesName")]) data class VodEntity(@PrimaryKey val id:String,val name:String,val contentType:String,val logoUrl:String?,val groupName:String,val description:String?,val year:Int?,val seasonNumber:Int?,val episodeNumber:Int?,val seriesName:String?,val favorite:Boolean=false)
@Entity(tableName="watch_history",indices=[Index("channelId"),Index("lastWatchedAt")]) data class WatchHistoryEntity(@PrimaryKey val id:String,val channelId:String,val name:String,val streamUrl:String,val logoUrl:String?,val groupName:String,val positionMs:Long,val durationMs:Long,val lastWatchedAt:Long)
@Dao interface PlaylistDao{@Query("SELECT * FROM playlists ORDER BY updatedAt DESC") fun observeAll():Flow<List<PlaylistEntity>>;@Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun save(item:PlaylistEntity)}
@Dao interface ChannelDao{@Query("SELECT * FROM channels ORDER BY groupName,name") fun observeAll():Flow<List<ChannelEntity>>;@Query("SELECT * FROM channels WHERE favorite=1 ORDER BY name") fun observeFavorites():Flow<List<ChannelEntity>>;@Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun saveAll(items:List<ChannelEntity>);@Query("DELETE FROM channels WHERE playlistId=:playlistId") suspend fun deleteForPlaylist(playlistId:String);@Query("UPDATE channels SET favorite=:favorite WHERE id=:id") suspend fun setFavorite(id:String,favorite:Boolean);@Query("SELECT id FROM channels WHERE favorite=1") suspend fun favoriteIds():List<String>}
@Dao interface VodDao{@Query("SELECT * FROM vod_items WHERE contentType='movie' ORDER BY groupName,name") fun observeMovies():Flow<List<VodEntity>>;@Query("SELECT * FROM vod_items WHERE contentType='series' ORDER BY seriesName,seasonNumber,episodeNumber,name") fun observeSeries():Flow<List<VodEntity>>;@Query("SELECT * FROM vod_items WHERE favorite=1 ORDER BY name") fun observeFavorites():Flow<List<VodEntity>>;@Query("SELECT id FROM vod_items WHERE favorite=1") suspend fun favoriteIds():List<String>;@Query("DELETE FROM vod_items") suspend fun clear();@Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun saveAll(items:List<VodEntity>);@Query("UPDATE vod_items SET favorite=:favorite WHERE id=:id") suspend fun setFavorite(id:String,favorite:Boolean)}
@Dao interface HistoryDao{@Query("SELECT * FROM watch_history ORDER BY lastWatchedAt DESC LIMIT 50") fun observeRecent():Flow<List<WatchHistoryEntity>>;@Query("SELECT * FROM watch_history WHERE durationMs>0 AND positionMs>0 AND positionMs<durationMs-30000 ORDER BY lastWatchedAt DESC LIMIT 20") fun observeContinue():Flow<List<WatchHistoryEntity>>;@Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun save(item:WatchHistoryEntity)}
@Database(entities=[PlaylistEntity::class,ChannelEntity::class,VodEntity::class,WatchHistoryEntity::class],version=4,exportSchema=false) abstract class AppDatabase:RoomDatabase(){abstract fun playlists():PlaylistDao;abstract fun channels():ChannelDao;abstract fun vod():VodDao;abstract fun history():HistoryDao
 companion object{@Volatile private var instance:AppDatabase?=null;fun get(context:Context)=instance?:synchronized(this){instance?:Room.databaseBuilder(context.applicationContext,AppDatabase::class.java,"superiptv.db").fallbackToDestructiveMigration().build().also{instance=it}}}}
